namespace gatelogic {

/// The task watchdog, as the loop sees it.
///
/// Kicked from the orchestration and NEVER from inside a driver, where it would
/// hide the stall it exists to end.
class IWatchdog {
public:
  virtual ~IWatchdog() = default;

  /// Restart the countdown.
  virtual void kick() = 0;
};

/// Whether the radio is associated.
///
/// Not const: the real implementation asks the driver, which is not a pure
/// read, and a port that promised constness would be lying about the one thing
/// it does.
class ILink {
public:
  virtual ~ILink() = default;

  virtual bool up() = 0;
};

/// Scanner bytes, plus the fact the plain byte port cannot carry.
///
/// A serial port's receive FIFO overruns silently: the driver drops whatever
/// did not fit and `read()` afterwards returns the bytes that DID, in order,
/// with nothing to say that a hole is in them. The assembler then trims a
/// perfectly printable line, finds it inside the token cap, and hands up a
/// token that is not what anybody scanned. `takeRxError()` is how that becomes
/// visible above the driver.
class IScannerBytes : public hal::IScannerPort {
public:
  /// True once for each error the driver has signalled since the last call,
  /// collapsed to a single flag and CLEARED by reading it. A flag rather than a
  /// count because the response is the same for one dropped byte and for two
  /// hundred: the line in flight is a hole and is discarded through its next
  /// terminator.
  virtual bool takeRxError() = 0;
};

} // namespace gatelogic

